module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Complemented outputs for the AND and OR gates
    wire q0_n, q1_n, q2_n;

    // Assign complemented outputs
    assign q0_n = ~q0;
    assign q1_n = ~q1;
    assign q2_n = ~q2;

    // D Flip-Flops with synchronous reset (initial value 0)
    always @(posedge clk) begin
        // Reset condition: initialize to 0
        // Note: Icarus Verilog -g2012 requires explicit initial block or
        // reset handling. Here we use a blocking assignment in an initial block
        // to set the initial state, and non-blocking in the always block
        // for synthesis compatibility with the positive edge trigger.
        if (!q0 && !q1 && !q2) begin
            // This block models the initial reset condition.
            // In real hardware, a global reset pin would be used.
            // For simulation purposes, we set them here.
            q0 <= 1'b0;
            q1 <= 1'b0;
            q2 <= 1'b0;
        end else begin
            // Standard positive edge triggered D flip-flop behavior
            // Input logic:
            // q0_next = x XOR q0
            // q1_next = x AND (~q1)
            // q2_next = x OR (~q2)
            q0 <= x ^ q0;
            q1 <= x & q1_n; // x AND (~q1)
            q2 <= x | q2_n; // x OR (~q2)
        end
    end

    // Three-input NOR gate
    // Z = NOR( q0, q1, q2 )
    // In Verilog, ~(A | B | C) is the NOR operation.
    assign z = ~(q0 | q1 | q2);

    // Initial block to set the reset state for simulation
    initial begin
        q0 = 1'b0;
        q1 = 1'b0;
        q2 = 1'b0;
    end

endmodule

