Prob154_fsm_ps2data.code:
module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 received bytes
    logic [23:0] shift_reg;

    // FSM state transition logic (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-asserted

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        shift_reg  <= {in, 16'b0}; // byte 1 in MSB
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive byte 2
                    next_state <= BYTE2;
                    shift_reg  <= {shift_reg[15:0], in}; // shift in byte 2
                end

                BYTE2: begin
                    // Receive byte 3
                    next_state <= BYTE3;
                    shift_reg  <= {shift_reg[7:0], in};  // shift in byte 3
                end

                BYTE3: begin
                    // All 3 bytes received; assert done in the NEXT cycle
                    // out_bytes is already valid with the assembled message
                    next_state <= IDLE;
                    done       <= 1'b1;
                end
            endcase
        end
    end

    // Output assignment: out_bytes is valid whenever done is asserted
    // (registered to avoid combinational loops, though here it is driven
    //  directly from shift_reg which updates on the same clock edge).
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            out_bytes <= 24'b0;
        else if (done)
            out_bytes <= shift_reg;
    end

endmodule

Prob149_ece241_2013_q4.code:
module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state register: 2 bits to encode 4 states
    reg [1:0] state;

    // Synchronous reset: go to the "low level for long time" state (3'b111)
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b111;  // equivalent to long-low condition
        end else begin
            // Determine next state based on current sensor vector s
            case (s)
                3'b111: state <= 3'b000; // Above s[2] -> no sensors
                3'b110: state <= 3'b001; // Between s[2] and s[1] -> s[0], s[1]
                3'b101: state <= 3'b010; // Between s[1] and s[0] -> s[0]
                3'b100, 3'b011, 3'b010, 3'b001, 3'b000: state <= 3'b011; // Below s[0] or transitional -> all sensors
                default: state <= 3'b111; // fallback
            endcase
        end
    end

    // Output logic: combinatorial assignment based on current state
    // fr0 is always asserted (per specification nominal flow always includes fr0)
    assign fr0 = 1'b1;

    // fr1 asserted when state indicates level between s[1] and s[0] (state 2'b010)
    assign fr1 = (state == 2'b010);

    // fr2 asserted when state indicates level below s[0] (state 2'b011)
    assign fr2 = (state == 2'b011);

    // dfr (Supplemental flow valve): asserted if the previous level was lower
    // than the current level, i.e., we are rising from a lower sensor.
    // We compare the current sensor vector with the previous state.
    // A rise occurs when we transition from a state with fewer sensors
    // to a state with more sensors (or from "below s[0]" to any higher level).
    // Since we only have the current s and the registered state,
    // we infer a rise if the new state has a higher index than the previous.
    // We define a simple heuristic: dfr = 1 when the new state is not 00
    // and the previous state was lower (state index < new state index).
    // For synthesis with Icarus Verilog g2012, we use a register to remember
    // the previous sensor pattern to detect edges.

    reg [2:0] s_prev;
    always @(posedge clk) begin
        if (reset) begin
            s_prev <= 3'b000;
        end else begin
            s_prev <= s;
        end
    end

    // dfr is high when the current level is higher than the previous level.
    // We detect this by observing that the previous sensor pattern had
    // a lower or equal assertion count, and the current pattern has more.
    // A simple edge detector: dfr = 1 if s has a rising transition
    // compared to s_prev (i.e., a bit changed from 0 to 1 that increases
    // the sensor index).
    assign dfr = (s & ~s_prev) != 3'b000; // any rising edge

endmodule

