    input  logic reset,
    input  logic x,
    output logic z
);

    // State assignment: y[2:0] corresponds to the present state
    logic [2:0] y, y_next;

    // Next-state logic (combinational)
    always_comb begin
        case (y)
            3'b000: begin
                y_next = (x == 1'b1) ? 3'b001 : 3'b000;
                z     = 1'b0;
            end
            3'b001: begin
                y_next = (x == 1'b1) ? 3'b100 : 3'b001;
                z     = 1'b0;
            end
            3'b010: begin
                y_next = (x == 1'b1) ? 3'b001 : 3'b010;
                z     = 1'b0;
            end
            3'b011: begin
                y_next = (x == 1'b1) ? 3'b010 : 3'b001;
                z     = 1'b1;
            end
            3'b100: begin
                y_next = (x == 1'b1) ? 3'b100 : 3'b011;
                z     = 1'b1;
            end
            default: begin
                y_next = 3'b000;
                z     = 1'b0;
            end
        endcase
    end

    // Flip-flops (sequential logic, positive edge triggered)
