module TopModule (
    input  [3:0] x,
    output f
);

    // Internal signals for decoded address bits
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // K-map derived expression:
    // f = x3' & x2' & x1 & x0'   (m1)
    //   | x3' & x2  & x1' & x0'  (m4)
    //   | x3  & x2  & x1         (m12, m13)
    //   | x3  & x2' & x1' & x0'  (m8, m9)
    //   | x3  & x2  & x1'        (m10, m11)
    //   | x3  & x2' & x1         (m9, m11) -> covered by above
    //   | x3' & x2  & x1'        (m5, m7)  -> don't care / overlap
    //   | x3' & x2' & x1' & x0   (m2)    -> don't care
    //
    // After prime implicant chart minimization:
    // f = (x3' & x2' & x1 & x0') |
    //     (x3' & x2  & x1' & x0') |
    //     (x3  & x2  & x1)       |
    //     (x3  & x2' & x1' & x0') |
    //     (x3  & x2  & x1')
    //
    // Further merging:
    // f = (x3' & x2' & x1 & x0') |
    //     (x3' & x2  & x1' & x0') |
    //     (x3  & x2  & x1)       |
    //     (x3  & x2' & x1' & x0') |
    //     (x3  & x2  & x1')
    //
    // Note: The term (x3 & x2 & x1) covers m12 (11,11) and m13 (11,10).
    // The term (x3 & x2 & x1') covers m10 (11,01) and m11 (11,00).
    // The term (x3 & x2' & x1' & x0') covers m8 (10,00) and m9 (10,01).
    // The term (x3 & x2' & x1)  covers m9 (10,01) and m11 (11,00) — merged with above.
    // The term (x3' & x2' & x1 & x0') covers m1 (00,01).
    // The term (x3' & x2  & x1' & x0') covers m4 (01,01).

    assign f = (~x3 & ~x2 &  x1 & ~x0) |
               (~x3 &  x2 & ~x1 & ~x0) |
               ( x3 &  x2 &  x1)       |
               ( x3 & ~x2 & ~x1 & ~x0) |
               ( x3 &  x2 & ~x1);

endmodule

