module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: BCD display
);

    // Internal register for the 4-digit BCD counter (16 bits)
    reg [15:0] q_reg;

    // Assign outputs
    assign q     = q_reg;
    assign ena   = q_reg[15:13]; // Upper 3 bits are the enables

    // Synchronous reset and positive-edge-triggered logic
    always @(posedge clk) begin
        if (reset) begin
            q_reg <= 16'd0;
        end else begin
            // BCD increment logic
            // Local signals for intermediate calculation
            reg [3:0] ones, tens, hundreds, thousands;
            reg [3:0] next_ones, next_tens, next_hundreds, next_thousands;
            reg carry;

            ones      = q_reg[3:0];
            tens      = q_reg[7:4];
            hundreds  = q_reg[11:8];
            thousands = q_reg[15:12];

            // Increment ones
            next_ones = ones + 1'b1;
            carry     = (ones == 4'd9);

            // Increment tens if carry from ones
            next_tens = tens + carry;
            carry     = (tens == 4'd9) & carry;

            // Increment hundreds if carry from tens
            next_hundreds = hundreds + carry;
            carry     = (hundreds == 4'd9) & carry;

            // Increment thousands if carry from hundreds
            next_thousands = thousands + carry;

            // Assemble next state
            q_reg <= {next_thousands, next_hundreds, next_tens, next_ones};
        end
    end

endmodule

