    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        WALK_LEFT,    // 0
        WALK_RIGHT,   // 1
        FALLING,      // 2
        DIGGING,      // 3
        SPLATTERED    // 4
    } state_t;

    state_t state, next_state;

    // Outputs: in a Moore machine, outputs are registered and depend only on state
    // walk_left and walk_right are mutually exclusive; only one can be 1 at a time
