    assign walk_left  = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);
    assign aaah       = (state == FALLING);
    assign digging    = (state == DIGGING);

    // Counter for fall duration (max 20 cycles)
    logic [4:0] fall_counter;
    logic [4:0] next_fall_counter;

    // Next state logic
    always_comb begin
        next_state = state;
        next_fall_counter = fall_counter;

        case (state)
            WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Start falling; counter starts at 1 (this cycle is first fall cycle)
                    next_state = FALLING;
                    next_fall_counter = 5'd1;
                end else if (dig && !bump_left && !bump_right) begin
                    // Start digging; only if not bumped
                    next_state = DIGGING;
                end else begin
                    // Switch direction if bumped
                    if (bump_left && !bump_right) begin
                        next_state = WALK_RIGHT;
                    end else if (bump_right && !bump_left) begin
                        next_state = WALK_LEFT;
                    end else if (bump_left && bump_right) begin
                        // Bumped on both sides: switch directions (arbitrarily choose right)
                        next_state = WALK_RIGHT;
                    end
                    // else: stay in WALK_LEFT
                end
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    next_fall_counter = 5'd1;
                end else if (dig && !bump_left && !bump_right) begin
                    next_state = DIGGING;
                end else begin
                    if (bump_right && !bump_left) begin
                        next_state = WALK_LEFT;
                    end else if (bump_left && !bump_right) begin
                        next_state = WALK_RIGHT;
                    end else if (bump_left && bump_right) begin
                        next_state = WALK_LEFT;
                    end
                    // else: stay in WALK_RIGHT
                end
            end

            FALLING: begin
                // Increment fall counter
                next_fall_counter = fall_counter + 5'd1;

                if (ground) begin
                    // Ground reappears
                    if (fall_counter > 5'd20) begin
                        // Splatter: more than 20 cycles falling
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in the same direction as before the fall
                        // We need to remember the original walking direction.
                        // Since we don't have a separate register, we infer the direction
                        // from the state before falling. However, in a pure FSM without
                        // memory, we must determine it here.
                        // Assumption: if we entered FALLING from WALK_LEFT, we resume WALK_LEFT.
