                        // we add a register 'last_walk_dir'.
                        // For this implementation, we will use a register to track it.
                        // But the spec says "resume walking in the same direction as before the fall".
                        // We'll handle this via a register below.
                        // For now, placeholder: we will set next_state based on a stored dir.
                        // Since we haven't defined that register yet, we'll default to WALK_LEFT
                        // but note that a full implementation requires the register.
                        // Re-evaluating: the specification says we must implement the behaviour.
                        // We need a register to store the walking direction before falling.
                        // We will add 'walk_dir_reg' as a reg.
                        // For the sake of this complete module, we will include that register.
                        // Here, we will just transition to a state that uses the register.
                        // Let's restructure: we will define the register and use it in the case.
                        // Since this is an always_comb for next_state, we need the register value.
                        // We'll declare the register in the always_ff block and use it here.
                        // To avoid forward reference issues, we will define the register
                        // and compute next_state using it in the sequential block or via functions.
                        // Given the format, we will provide the full code with the register.
                    end
                end else begin
                    // Still falling; bumping has no effect
                    // Stay in FALLING
                end
            end

            DIGGING: begin
                if (!ground) begin
                    // Start falling
                    next_state = FALLING;
                    next_fall_counter = 5'd1;
                end else begin
                    // Continue digging; bumping has no effect
                    // Stay in DIGGING
                end
            end

            SPLATTERED: begin
                // Forever stuck; no transitions
                next_state = SPLATTERED;
                next_fall_counter = 5'd0;
            end
        endcase
    end

    // Sequential block: registers update on positive edge of clk
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
            fall_counter <= 5'd0;
