    end

    // We need a register to remember the walking direction before falling/digging.
    // We'll add it here and drive it in the sequential block.
    logic walk_dir_reg; // 0 = left, 1 = right

    // Update walk_dir_reg when transitioning from walking states
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            walk_dir_reg <= 1'b0;
        end else begin
            // If next_state is FALLING or DIGGING and current state is a walking state,
            // store the current walking direction.
            if ((state == WALK_LEFT || state == WALK_RIGHT) &&
                (next_state == FALLING || next_state == DIGGING)) begin
                if (state == WALK_LEFT)
                    walk_dir_reg <= 1'b0;
                else
                    walk_dir_reg <= 1'b1;
            end
            // If we are resuming from fall (not splattered), we don't change walk_dir_reg
            // because it already holds the direction we were walking before the fall.
            // Actually, we need to ensure that when we resume, we use that direction.
            // The transition from FALLING to walking will use walk_dir_reg.
        end
    end

    // Revised next_state logic incorporating walk_dir_reg
    always_comb begin
        next_state = state;
        next_fall_counter = fall_counter;

        case (state)
            WALK_LEFT: begin
                if (!ground) begin
                    next_state = FALLING;
                    next_fall_counter = 5'd1;
                end else if (dig && !bump_left && !bump_right) begin
                    next_state = DIGGING;
                end else begin
                    if (bump_left && !bump_right) begin
                        next_state = WALK_RIGHT;
                    end else if (bump_right && !bump_left) begin
                        next_state = WALK_LEFT;
                    end else if (bump_left && bump_right) begin
                        next_state = WALK_RIGHT;
                    end
                end
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    next_fall_counter = 5'd1;
                end else if (dig && !bump_left && !bump_right) begin
                    next_state = DIGGING;
                end else begin
                    if (bump_right && !bump_left) begin
                        next_state = WALK_LEFT;
                    end else if (bump_left && !bump_right) begin
                        next_state = WALK_RIGHT;
                    end else if (bump_left && bump_right) begin
                        next_state = WALK_LEFT;
                    end
                end
            end

            FALLING: begin
                next_fall_counter = fall_counter + 5'd1;

                if (ground) begin
                    if (fall_counter > 5'd20) begin
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in the same direction as before the fall
                        if (walk_dir_reg == 1'b0)
                            next_state = WALK_LEFT;
                        else
                            next_state = WALK_RIGHT;
                    end
                end
                // else: stay in FALLING
            end

            DIGGING: begin
                if (!ground) begin
                    next_state = FALLING;
                    next_fall_counter = 5'd1;
                end else begin
                    next_state = DIGGING;
                end
            end

            SPLATTERED: begin
                next_state = SPLATTERED;
                next_fall_counter = 5'd0;
            end
        endcase
    end

endmodule

