module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  state [9:0],
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // Internal signals for current state decoding
    wire S       = state[0];
    wire S1      = state[1];
    wire S11     = state[2];
    wire S110    = state[3];
    wire B0      = state[4];
    wire B1      = state[5];
    wire B2      = state[6];
    wire B3      = state[7];
    wire Count   = state[8];
    wire Wait    = state[9];

    // ============================================
    // Next-state logic (one-hot encoded flip-flops)
    // ============================================
    // S_next: Assert when next-state is S
    // Transitions to S: S (d=0), S1 (d=0), S110 (d=0), Wait (ack=1)
    assign S_next = (S & ~d) | (S1 & ~d) | (S110 & ~d) | (Wait & ack);

    // S1_next: Assert when next-state is S1
    // Transitions to S1: S (d=1), S1 (d=1), S11 (d=1)
    assign S1_next = (S & d) | (S1 & d) | (S11 & d);

    // Count_next: Assert when next-state is Count
    // Transitions to Count: B3 (always goes to Count next cycle)
    assign Count_next = B3;

    // Wait_next: Assert when next-state is Wait
    // Transitions to Wait: Count (done_counting=1)
    assign Wait_next = Count & done_counting;

    // B3_next: Assert when next-state is B3
    // Transitions to B3: B2 (always goes to B3 next cycle)
    assign B3_next = B2;

    // ============================================
    // Output logic (Moore machine - outputs depend only on current state)
    // ============================================
    // shift_ena: Asserted in B0, B1, B2, B3 states
    assign shift_ena = B0 | B1 | B2 | B3;

    // counting: Asserted in Count state
    assign counting = Count;

    // done: Asserted in Wait state
    assign done = Wait;

endmodule

