module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 4 bits required for the 10 distinct states
    typedef enum logic [3:0] {
        S_A   = 4'b0000, // Reset/Idle state
        S_B   = 4'b0001, // f=1 pulse state
        S_P0  = 4'b0010, // Waiting for first x=1
        S_P1  = 4'b0011, // Last x was 1
        S_P2  = 4'b0100, // Last two x were 1,0
        S_P3  = 4'b0101, // Pattern 1,0,1 detected, g=1 active (enter y-monitor)
        S_Y1  = 4'b0110, // g=1, monitoring y cycle 1
        S_Y2  = 4'b0111, // g=1, monitoring y cycle 2
        S_Y_OK= 4'b1000, // g=1 permanent (y=1 seen within 2 cycles)
        S_Y_FAIL=4'b1001 // g=0 permanent (y never became 1 within 2 cycles)
    } state_t;

    state_t state, next_state;

    // Output assignments (combinational)
    // f is 1 only in state B
    assign f = (state == S_B);

    // g is 1 in states S_P3, S_Y1, S_Y2, S_Y_OK
    assign g = (state == S_P3) || (state == S_Y1) || (state == S_Y2) || (state == S_Y_OK);

    // State register (positive edge triggered, synchronous active low reset)
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= S_A;
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic (combinational)
    always_comb begin
        // Default: stay in current state
        next_state = state;

        case (state)
            S_A: begin
                // On de-assertion of reset, go to S_B after next clock edge
                next_state = S_B;
            end

            S_B: begin
                // f pulse over, start monitoring x input
                next_state = S_P0;
            end

            S_P0: begin
                // Waiting for the first '1' in the x sequence
                if (x == 1) begin
                    next_state = S_P1;
                end else begin
                    next_state = S_P0;
                end
            end

            S_P1: begin
                // We have seen a '1'. Now expecting a '0'.
                if (x == 1) begin
                    // Another '1' resets the expectation to just having seen a '1'
                    next_state = S_P1;
                end else if (x == 0) begin
                    // Saw 1, then 0. Move to expecting 1.
                    next_state = S_P2;
                end else begin
                    next_state = S_P1;
                end
            end

            S_P2: begin
                // We have seen '1', '0'. Now expecting a '1'.
                if (x == 1) begin
                    // Pattern 1,0,1 detected! Move to y-monitoring state.
                    next_state = S_P3;
                end else if (x == 0) begin
                    // Pattern broken (got 0 instead of 1).
                    // The last value is 0, so we go back to waiting for a new '1'.
                    next_state = S_P0;
                end else begin
                    next_state = S_P2;
                end
            end

            S_P3: begin
                // Pattern 1,0,1 detected. g is 1 now. Start monitoring y.
                // g will be 1 in this state and the next two y-monitoring states.
                next_state = S_Y1;
            end

            S_Y1: begin
                // First cycle of y monitoring.
                if (y == 1) begin
                    // y=1 seen within the allowed window. g goes permanent.
                    next_state = S_Y_OK;
                end else begin
                    // y=0. Wait for the second cycle.
                    next_state = S_Y2;
                end
            end

            S_Y2: begin
                // Second and final cycle of y monitoring.
                if (y == 1) begin
                    // y=1 seen within the allowed window. g goes permanent.
                    next_state = S_Y_OK;
                end else begin
                    // y=0 seen in both cycles. g goes permanent 0.
                    next_state = S_Y_FAIL;
                end
            end

            S_Y_OK: begin
                // g=1 permanent. Stay in this state until reset.
                next_state = S_Y_OK;
            end

            S_Y_FAIL: begin
                // g=0 permanent. Stay in this state until reset.
                next_state = S_Y_FAIL;
            end

            default: begin
                next_state = S_A;
            end
        endcase
    end

endmodule
